package com.order.order_service.service;
import com.order.order_service.repository.OrderItemRepository;import com.order.order_service.repository.OrderRepository;import java.math.BigDecimal;import java.time.LocalDate;import java.time.LocalDateTime;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Service;
@Service public class AdminReportService{private final OrderRepository orders;private final OrderItemRepository items;public AdminReportService(OrderRepository o,OrderItemRepository i){orders=o;items=i;}public Map<String,Object> summary(LocalDate from,LocalDate to){if(from==null)from=LocalDate.now().minusDays(30);if(to==null)to=LocalDate.now();range(from,to);LocalDateTime start=from.atStartOfDay(),end=to.plusDays(1).atStartOfDay();Map<String,Long> statuses=new LinkedHashMap<>();for(Object[] r:orders.statusCounts(start,end))statuses.put(((Enum<?>)r[0]).name(),((Number)r[1]).longValue());return Map.of("from",from,"to",to,"orders",orders.countCreatedBetween(start,end),"nonCancelledOrderValue",orders.sumRevenueBetween(start,end),"statuses",statuses,"topItems",topItems(start,end));}private List<Map<String,Object>> topItems(LocalDateTime from,LocalDateTime to){List<Map<String,Object>> rows=new ArrayList<>();for(Object[] r:items.topItems(from,to,PageRequest.of(0,10))){Map<String,Object> item=new LinkedHashMap<>();item.put("itemName",r[0]);item.put("quantity",r[1]);item.put("grossSales",Objects.toString(r[2],"0"));rows.add(item);}return rows;}private void range(LocalDate from,LocalDate to){if(to.isBefore(from)||from.plusDays(366).isBefore(to))throw new IllegalArgumentException("Report range must be ordered and no longer than 367 days");}}
